type Patient = { id: string; full_name: string; phone: string; convenio: string | null; birth_date: string | null; email: string | null; notes: string | null; address: string | null; birthplace: string | null; marital_status: string | null; created_at: string };
const MARITAL = ["Solteiro(a)", "Casado(a)", "União estável", "Divorciado(a)", "Viúvo(a)"] as const;
type Appointment = { id: string; patient_id: string; date: string; time: string; status: string; kind: string; cancellation_reason: string | null };
const DAYS = [["1", "Segunda-feira"], ["2", "Terça-feira"], ["3", "Quarta-feira"], ["4", "Quinta-feira"], ["5", "Sexta-feira"], ["6", "Sábado"], ["7", "Domingo"]] as const;
type DayKey = (typeof DAYS)[number][0]; type DayConfig = { open: boolean; start: string; end: string }; type WeekDays = Record<DayKey, DayConfig>;
type Schedule = { start_time: string; end_time: string; interval_minutes: number; week_days: WeekDays | null };
type View = "agenda" | "pacientes" | "relatorios" | "canceladas" | "configuracoes";
const patientSchema = z.object({ full_name: z.string().trim().min(2, "Informe o nome completo.").max(120), phone: z.string().trim().min(8, "Informe um telefone válido.").max(30), convenio: z.enum(["Santa Saúde", "Unimed", "Particular"], { message: "Selecione o convênio." }), birth_date: z.string().optional(), email: z.union([z.literal(""), z.string().email("E-mail inválido.").max(255)]), notes: z.string().max(2000), address: z.string().trim().max(300, "Endereço muito longo."), birthplace: z.string().trim().max(120, "Naturalidade muito longa."), marital_status: z.string().max(40) });
const today = () => format(new Date(), "yyyy-MM-dd");
const prettyDate = (date: string) => format(parseISO(date), "dd 'de' MMMM 'de' yyyy", { locale: ptBR });
const shortDate = (date: string) => format(parseISO(date), "dd/MM/yyyy");
const timeLabel = (time: string) => time.slice(0, 5);
const statusName = (s: string) => ({ agendado: "Agendado", "em atendimento": "Em atendimento", "concluído": "Concluído", cancelado: "Cancelado" })[s as "agendado"] ?? s;
const statusClass = (s: string) => ({ agendado: "status-agendado", "em atendimento": "status-em-atendimento", "concluído": "status-concluido", cancelado: "status-cancelado" })[s as "agendado"] ?? "status-disponivel";
function weekDays(schedule: Schedule): WeekDays { return Object.fromEntries(DAYS.map(([k]) => [k, schedule.week_days?.[k] ?? { open: Number(k) <= 5, start: timeLabel(schedule.start_time), end: timeLabel(schedule.end_time) }])) as WeekDays; }
function slots(schedule: Schedule, date: string) { const d = weekDays(schedule)[String(getISODay(parseISO(date))) as DayKey]; if (!d.open) return []; const [sh = 9, sm = 0] = d.start.split(":").map(Number); const [eh = 18, em = 0] = d.end.split(":").map(Number); const list: string[] = []; for (let n = sh * 60 + sm; n <= eh * 60 + em; n += schedule.interval_minutes) list.push(`${String(Math.floor(n / 60)).padStart(2, "0")}:${String(n % 60).padStart(2, "0")}`); return list; }
function Badge({ status }: { status: string }) { return <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-bold whitespace-nowrap ${statusClass(status)}`}><span className="size-1.5 rounded-full bg-current" />{statusName(status)}</span>; }
const CONVENIOS = [{ name: "Santa Saúde", logo: santaSaudeLogo.url }, { name: "Unimed", logo: unimedLogo.url }, { name: "Particular", logo: particularLogo.url }] as const;
function ConvenioTag({ name }: { name: string | null }) { const c = CONVENIOS.find(x => x.name === name); if (!c) return <span className="font-semibold">{name || "—"}</span>; return <span className="inline-flex items-center gap-2 font-semibold"><img src={c.logo} alt={`Logo ${c.name}`} className="h-6 w-auto max-w-[80px] object-contain rounded" />{c.name}</span>; }
function lastVisitInfo(list: Appointment[], patientId: string, refDate: string) { const last = list.filter(a => a.patient_id === patientId && a.status === "concluído" && a.date <= refDate).sort((a,b) => (b.date + b.time).localeCompare(a.date + a.time))[0]; const days = last ? differenceInCalendarDays(parseISO(refDate), parseISO(last.date)) : null; return { last, days, isReturn: days !== null && days <= 30 }; }
const emptyForm = { full_name: "", phone: "", convenio: "", birth_date: "", email: "", notes: "", address: "", birthplace: "", marital_status: "" };
type FichaForm = { full_name: string; day: string; month: string; year: string; address: string; phone: string; convenio: string; birthplace: string; marital_status: string; age: string };
const emptyFicha: FichaForm = { full_name: "", day: "", month: "", year: "", address: "", phone: "", convenio: "", birthplace: "", marital_status: "", age: "" };
function fichaBirth(f: Pick<FichaForm, "day" | "month" | "year">) { if (!f.day || !f.month || f.year.length !== 4) return null; const iso = `${f.year}-${f.month.padStart(2, "0")}-${f.day.padStart(2, "0")}`; const d = parseISO(iso); return Number.isNaN(d.getTime()) || format(d, "yyyy-MM-dd") !== iso ? null : iso; }
function fichaFromPatient(p: Patient | null): FichaForm { if (!p) return emptyFicha; const [year = "", month = "", day = ""] = (p.birth_date ?? "").split("-"); return { full_name: p.full_name, day, month, year, address: p.address ?? "", phone: p.phone, convenio: p.convenio ?? "", birthplace: p.birthplace ?? "", marital_status: p.marital_status ?? "", age: p.birth_date ? `${differenceInYears(new Date(), parseISO(p.birth_date))} anos` : "" }; }
function FichaValue({ staticMode, ...props }: React.InputHTMLAttributes<HTMLInputElement> & { staticMode?: boolean | undefined }) { return staticMode ? <span className={`${props.className ?? ""} block min-h-[1.6rem] whitespace-pre-wrap break-words`}>{props.value}</span> : <input {...props} />; }
const fichaInput = "w-full min-w-0 bg-transparent border-0 border-b-2 border-primary/70 rounded-none px-1 pb-0.5 text-foreground outline-none focus:border-primary focus:bg-info-soft/60 print:focus:bg-transparent";
function FichaLine({ icon: Icon, label, value, onChange, list, maxLength = 120, inputMode, staticMode }: { staticMode?: boolean | undefined; icon: typeof UserRound; label: string; value: string; onChange: (v: string) => void; list?: string; maxLength?: number; inputMode?: "tel" | "numeric" }) { return <label className="flex items-end gap-3 min-w-0"><Icon className="size-7 shrink-0 text-secondary-foreground" strokeWidth={1.8} /><span className="font-bold text-secondary-foreground whitespace-nowrap">{label}:</span><FichaValue staticMode={staticMode} className={fichaInput} value={value} list={list} maxLength={maxLength} inputMode={inputMode} onChange={e => onChange(e.target.value)} /></label>; }
function FichaPaciente({ value, onChange, staticMode = false }: { value: FichaForm; onChange: (patch: Partial<FichaForm>) => void; staticMode?: boolean }) {
  function setBirth(patch: Partial<Pick<FichaForm, "day" | "month" | "year">>) { const next = { ...value, ...patch }; const iso = fichaBirth(next); onChange(iso ? { ...patch, age: `${differenceInYears(new Date(), parseISO(iso))} anos` } : patch); }
  const digits = (v: string, n: number) => v.replace(/\D/g, "").slice(0, n);
  return <div className="rounded-xl border-2 border-primary bg-card p-5 sm:p-7 text-sm">
    <div className="flex items-center gap-5 mb-7"><div className="relative size-16 shrink-0 text-secondary-foreground"><Cross className="size-16" strokeWidth={1.6} /><Activity className="size-7 absolute inset-0 m-auto" strokeWidth={2} /></div><div className="w-px h-16 bg-secondary-foreground/60" /><h2 className="text-2xl sm:text-3xl font-extrabold leading-tight text-secondary-foreground uppercase">Ficha de cadastro<br />de paciente</h2></div>
    <div className="grid sm:grid-cols-2 gap-x-8 gap-y-6">
      <FichaLine staticMode={staticMode} icon={UserRound} label="Nome completo" value={value.full_name} onChange={v => onChange({ full_name: v })} />
      <div className="flex items-end gap-3"><CalendarDays className="size-7 shrink-0 text-secondary-foreground" strokeWidth={1.8} /><span className="font-bold text-secondary-foreground whitespace-nowrap">Data de nascimento:</span><span className="flex-1 flex items-end gap-1"><FichaValue staticMode={staticMode} aria-label="Dia de nascimento" placeholder="dd" className={`${fichaInput} text-center placeholder:text-muted-foreground/50 print:placeholder:text-transparent`} inputMode="numeric" value={value.day} onChange={e => setBirth({ day: digits(e.target.value, 2) })} /><span className="font-bold text-secondary-foreground">/</span><FichaValue staticMode={staticMode} aria-label="Mês de nascimento" placeholder="mm" className={`${fichaInput} text-center placeholder:text-muted-foreground/50 print:placeholder:text-transparent`} inputMode="numeric" value={value.month} onChange={e => setBirth({ month: digits(e.target.value, 2) })} /><span className="font-bold text-secondary-foreground">/</span><FichaValue staticMode={staticMode} aria-label="Ano de nascimento" placeholder="aaaa" className={`${fichaInput} text-center placeholder:text-muted-foreground/50 print:placeholder:text-transparent`} inputMode="numeric" value={value.year} onChange={e => setBirth({ year: digits(e.target.value, 4) })} /></span></div>
      <FichaLine staticMode={staticMode} icon={House} label="Endereço" value={value.address} maxLength={300} onChange={v => onChange({ address: v })} />
      <FichaLine staticMode={staticMode} icon={Phone} label="Telefone" value={value.phone} maxLength={30} inputMode="tel" onChange={v => onChange({ phone: v })} />
      <FichaLine staticMode={staticMode} icon={FileText} label="Convênio" value={value.convenio} list="ficha-convenios" onChange={v => onChange({ convenio: v })} />
      <FichaLine staticMode={staticMode} icon={MapPin} label="Naturalidade" value={value.birthplace} onChange={v => onChange({ birthplace: v })} />
      <FichaLine staticMode={staticMode} icon={HeartHandshake} label="Estado civil" value={value.marital_status} maxLength={40} list="ficha-estado-civil" onChange={v => onChange({ marital_status: v })} />
      <FichaLine staticMode={staticMode} icon={UserRound} label="Idade" value={value.age} maxLength={20} onChange={v => onChange({ age: v })} />
    </div>
    <datalist id="ficha-convenios">{CONVENIOS.map(c => <option key={c.name} value={c.name} />)}</datalist>
    <datalist id="ficha-estado-civil">{MARITAL.map(m => <option key={m} value={m} />)}</datalist>
  </div>;
}

export function ClinicApp({ user }: { user: User }) {
  const [view, setView] = useState<View>("agenda"); const [date, setDate] = useState(today());
  const [patients, setPatients] = useState<Patient[]>([]); const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [schedule, setSchedule] = useState<Schedule>({ start_time: "09:00", end_time: "18:00", interval_minutes: 15, week_days: null });
  const [loaded, setLoaded] = useState(false); const [error, setError] = useState(""); const [notice, setNotice] = useState("");
  const [search, setSearch] = useState(""); const [modal, setModal] = useState<"booking" | "patient" | "detail" | "cancel" | "ficha" | null>(null); const [fichaId, setFichaId] = useState(""); const [ficha, setFicha] = useState<FichaForm>(emptyFicha);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null); const [selectedAppointment, setSelectedAppointment] = useState<Appointment | null>(null);
  const [bookingDate, setBookingDate] = useState(today()); const [bookingTime, setBookingTime] = useState(""); const [bookingPatient, setBookingPatient] = useState(""); const [bookingSearch, setBookingSearch] = useState(""); const [newPatient, setNewPatient] = useState(false);
  const [form, setForm] = useState(emptyForm); const [reason, setReason] = useState(""); const [saving, setSaving] = useState(false); const [menuOpen, setMenuOpen] = useState(false); const [dayKey, setDayKey] = useState<DayKey>("1");
  async function refresh() {
    const [p, a, s] = await Promise.all([supabase.from("patients").select("*").order("full_name"), supabase.from("appointments").select("*").order("date", { ascending: false }), supabase.from("schedule_settings").select("start_time,end_time,interval_minutes,week_days").eq("owner_id", user.id).maybeSingle()]);
    if (p.error || a.error || s.error) setError(p.error?.message ?? a.error?.message ?? s.error?.message ?? "Não foi possível carregar os dados.");
    else { setPatients(p.data ?? []); setAppointments(a.data ?? []); if (s.data) setSchedule({ ...s.data, week_days: s.data.week_days as WeekDays | null }); setError(""); }
    setLoaded(true);
  }
  useEffect(() => { void refresh(); }, [user.id]);
  const day = appointments.filter(a => a.date === date); const active = day.filter(a => a.status !== "cancelado");
  const cancelled = appointments.filter(a => a.status === "cancelado");
  const dailySlots = useMemo(() => [...new Set([...slots(schedule, date), ...active.map(a => timeLabel(a.time))])].sort(), [schedule, date, active]); const isClosed = dailySlots.length === 0;
  const next = active.filter(a => a.date >= today() && (a.date > today() || timeLabel(a.time) >= format(new Date(), "HH:mm"))).sort((a,b) => `${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`))[0] ?? appointments.filter(a => a.status !== "cancelado" && a.date >= today()).sort((a,b) => `${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`))[0];
  const patientOf = (id: string) => patients.find(p => p.id === id);
  const filteredPatients = patients.filter(p => `${p.full_name} ${p.phone} ${p.convenio ?? ""}`.toLowerCase().includes(search.toLowerCase()));
  function notify(text: string) { setNotice(text); window.setTimeout(() => setNotice(""), 4000); }
  function openBooking(d = date, t = "", patientId = "") { setBookingDate(d); setBookingTime(t); setBookingPatient(patientId); setBookingSearch(""); setNewPatient(false); setForm(emptyForm); setError(""); setModal("booking"); }
  function openPatient(patient: Patient, editing = false) { setSelectedPatient(patient); setForm({ full_name: patient.full_name, phone: patient.phone, convenio: patient.convenio ?? "", birth_date: patient.birth_date ?? "", email: patient.email ?? "", notes: patient.notes ?? "", address: patient.address ?? "", birthplace: patient.birthplace ?? "", marital_status: patient.marital_status ?? "" }); setModal(editing ? "patient" : "detail"); }
  function pickFicha(id: string) { setFichaId(id); setFicha(fichaFromPatient(id ? patientOf(id) ?? null : null)); setError(""); }
  async function saveFicha() { setError(""); const anyBirth = ficha.day || ficha.month || ficha.year; const birth = fichaBirth(ficha); if (anyBirth && !birth) { setError("Data de nascimento inválida. Use dia, mês e ano (ex.: 05 / 03 / 1990)."); return; }
    const existing = fichaId ? patientOf(fichaId) : undefined;
    const parsed = patientSchema.safeParse({ full_name: ficha.full_name, phone: ficha.phone, convenio: ficha.convenio, birth_date: birth ?? "", email: existing?.email ?? "", notes: existing?.notes ?? "", address: ficha.address, birthplace: ficha.birthplace, marital_status: ficha.marital_status });
    if (!parsed.success) { setError(parsed.error.issues[0]?.path[0] === "convenio" ? "Convênio deve ser Santa Saúde, Unimed ou Particular." : parsed.error.issues[0]?.message ?? "Verifique os dados."); return; }
    setSaving(true); const payload = { ...parsed.data, birth_date: birth, email: parsed.data.email || null, address: parsed.data.address || null, birthplace: parsed.data.birthplace || null, marital_status: parsed.data.marital_status || null, owner_id: user.id };
    const result = existing ? await supabase.from("patients").update(payload).eq("id", existing.id).select().single() : await supabase.from("patients").insert(payload).select().single(); setSaving(false);
    if (result.error) { setError(result.error.message); return; }
    await refresh(); if (result.data) setFichaId(result.data.id); notify(existing ? "Ficha salva no cadastro do paciente." : "Paciente cadastrado pela ficha.");
  }
  function close() { setModal(null); setError(""); setSelectedAppointment(null); }
  async function savePatient(e: React.FormEvent) { e.preventDefault(); const parsed = patientSchema.safeParse(form); if (!parsed.success) { setError(parsed.error.issues[0]?.message ?? "Verifique os dados."); return; } setSaving(true); const payload = { ...parsed.data, convenio: parsed.data.convenio || null, birth_date: parsed.data.birth_date || null, email: parsed.data.email || null, address: parsed.data.address || null, birthplace: parsed.data.birthplace || null, marital_status: parsed.data.marital_status || null, owner_id: user.id };
    const result = selectedPatient ? await supabase.from("patients").update(payload).eq("id", selectedPatient.id).select().single() : await supabase.from("patients").insert(payload).select().single(); setSaving(false);
    if (result.error) { setError(result.error.message); return null; }
    await refresh(); setError(""); if (result.data) setSelectedPatient(result.data); notify(selectedPatient ? "Paciente atualizado." : "Paciente cadastrado."); return result.data as Patient;
  }
  async function createPatient(e: React.FormEvent) { const result = await savePatient(e); if (result) { setBookingPatient(result.id); setNewPatient(false); setBookingSearch(result.full_name); setModal("booking"); } }
  async function book(e: React.FormEvent) { e.preventDefault(); setError(""); if (!bookingPatient) { setError("Selecione ou cadastre um paciente."); return; } if (slots(schedule, bookingDate).length === 0) { setError("O consultório não atende neste dia."); return; } if (!slots(schedule, bookingDate).includes(bookingTime)) { setError("Escolha um horário dentro do funcionamento."); return; } if (appointments.some(a => a.date === bookingDate && timeLabel(a.time) === bookingTime && a.status !== "cancelado")) { setError("Este horário já está ocupado."); return; }
    const previous = appointments.filter(a => a.patient_id === bookingPatient && a.status === "concluído" && a.date <= bookingDate).sort((a,b) => b.date.localeCompare(a.date))[0];
    const kind = previous && differenceInCalendarDays(parseISO(bookingDate), parseISO(previous.date)) <= 30 ? "retorno" : "consulta";
    setSaving(true); const { error: err } = await supabase.from("appointments").insert({ owner_id: user.id, patient_id: bookingPatient, date: bookingDate, time: bookingTime, kind, status: "agendado" }); setSaving(false);
    if (err) { setError(err.code === "23505" ? "Este horário acabou de ser reservado. Escolha outro." : err.message); return; }
    setDate(bookingDate); setView("agenda"); close(); await refresh(); notify(kind === "retorno" ? "Retorno agendado automaticamente." : "Consulta agendada com sucesso.");
  }
  async function updateStatus(a: Appointment, status: string, cancellationReason: string | null = null) { setSaving(true); const { error: err } = await supabase.from("appointments").update({ status, cancellation_reason: cancellationReason }).eq("id", a.id); setSaving(false); if (err) setError(err.message); else { close(); await refresh(); notify(status === "cancelado" ? "Consulta cancelada. O horário está disponível novamente." : "Status atualizado."); } }
  function moveDate(n: number) { setDate(format(addDays(parseISO(date), n), "yyyy-MM-dd")); }
  function setGlobalTime(field: "start_time" | "end_time", value: string) { const key = field === "start_time" ? "start" : "end"; const old = timeLabel(schedule[field]); const wd = weekDays(schedule); setSchedule({ ...schedule, [field]: value, week_days: Object.fromEntries(DAYS.map(([k]) => [k, wd[k][key] === old ? { ...wd[k], [key]: value } : wd[k]])) as WeekDays }); }
  function setDay(k: DayKey, patch: Partial<DayConfig>) { const wd = weekDays(schedule); setSchedule({ ...schedule, week_days: { ...wd, [k]: { ...wd[k], ...patch } } }); }
  async function saveSchedule(e: React.FormEvent) { e.preventDefault(); if (schedule.start_time >= schedule.end_time) { setError("O horário final deve ser após o horário inicial."); return; } const wd = weekDays(schedule); const badDay = DAYS.find(([k]) => wd[k].open && wd[k].start >= wd[k].end); if (badDay) { setError(`${badDay[1]}: o horário final deve ser após o horário inicial.`); return; } setSaving(true); const { error: err } = await supabase.from("schedule_settings").upsert({ owner_id: user.id, ...schedule, week_days: wd }); setSaving(false); if (err) setError(err.message); else { setError(""); notify("Horários de funcionamento salvos."); } }
  const nav: { key: View; label: string; icon: typeof CalendarDays }[] = [{ key: "agenda", label: "Agenda", icon: CalendarDays }, { key: "pacientes", label: "Pacientes", icon: UserRound }, { key: "relatorios", label: "Relatórios", icon: ChartNoAxesColumn }, { key: "configuracoes", label: "Configurações", icon: Settings2 }];
  const patientHistory = selectedPatient ? appointments.filter(a => a.patient_id === selectedPatient.id).sort((a,b) => `${b.date}${b.time}`.localeCompare(`${a.date}${a.time}`)) : [];
  const bookingSlots = slots(schedule, bookingDate); const bookingClosed = bookingSlots.length === 0;
  return <div className="min-h-screen lg:flex">
    <aside className={`bg-sidebar text-sidebar-foreground lg:w-[222px] lg:fixed lg:inset-y-0 z-30 flex flex-col ${menuOpen ? "fixed inset-y-0 left-0 w-[240px] shadow-xl" : "hidden lg:flex"}`}>
      <div className="h-[88px] flex items-center gap-2.5 px-6 border-b border-sidebar-muted/15"><HeartPulse className="size-9 text-primary" /><div><div className="font-extrabold text-lg leading-5">VidaSaúde</div><div className="text-[10px] text-sidebar-muted">Clínica Médica</div></div></div>
      <nav className="px-3 pt-7 space-y-1" aria-label="Menu principal">{nav.map(n => <Button key={n.key} variant="ghost" onClick={() => { setView(n.key); setMenuOpen(false); setSearch(""); }} className={`w-full justify-start h-11 px-4 font-medium ${view === n.key ? "bg-primary/25 text-sidebar-foreground hover:bg-primary/30" : "text-sidebar-muted hover:bg-primary/15 hover:text-sidebar-foreground"}`}><n.icon className="size-[17px]" />{n.label}</Button>)}</nav>
    </aside>
    <div className="lg:ml-[222px] w-full min-w-0">
      <header className="bg-card border-b border-border px-5 lg:px-8 h-[68px] flex items-center gap-4 justify-between sticky top-0 z-20"><div className="flex items-center gap-2"><Button variant="ghost" size="icon" className="lg:hidden" onClick={() => setMenuOpen(!menuOpen)} aria-label="Abrir menu"><Menu /></Button><span className="font-extrabold text-primary lg:hidden">VidaSaúde</span><span className="hidden lg:block font-semibold text-sm text-muted-foreground">{view === "agenda" ? "Painel principal" : nav.find(n => n.key === view)?.label}</span></div><div className="flex items-center gap-3"><div className="relative hidden sm:block"><Search className="size-4 absolute left-3 top-2.5 text-muted-foreground" /><input aria-label="Buscar paciente pelo nome, telefone ou convênio" className="field text-xs pl-9 w-[270px]" placeholder="Buscar paciente pelo nome, telefone ou convênio..." value={search} onChange={e => { setSearch(e.target.value); if (e.target.value) setView("pacientes"); }} /></div><Bell className="size-4 text-muted-foreground hidden sm:block" /><div className="w-px h-7 bg-border hidden sm:block" /><div className="size-8 rounded-full bg-info-soft text-primary flex items-center justify-center font-bold text-xs">{(user.email ?? "U")[0]?.toUpperCase()}</div><div className="hidden md:block text-xs"><b>{user.email?.split("@")[0]}</b><p className="text-muted-foreground">Minha conta</p></div><Button variant="ghost" size="icon" onClick={() => supabase.auth.signOut()} title="Sair" aria-label="Sair"><LogOut className="size-4" /></Button></div></header>
      <main className="p-4 md:p-6 lg:p-8 max-w-[1600px] mx-auto">
        {notice && <div role="status" className="mb-4 rounded-md bg-success-soft text-success px-4 py-2 text-sm font-semibold">{notice}</div>}
        {error && !modal && <div role="alert" className="mb-4 rounded-md bg-danger-soft text-destructive px-4 py-2 text-sm">{error}</div>}
        {!loaded ? <div className="py-20 text-center text-muted-foreground">Carregando agenda...</div> : <>
        {view === "agenda" && <>
          <div className="flex flex-wrap items-start justify-between gap-4 mb-6"><div><h1 className="text-2xl md:text-[28px] font-extrabold">Olá, {typeof user.user_metadata?.["full_name"] === "string" ? user.user_metadata["full_name"].split(" ")[0] : user.email?.split("@")[0] ?? "Doutor(a)"}!</h1><p className="text-muted-foreground text-sm mt-1">Aqui está o resumo da sua agenda de hoje.</p></div><Button onClick={() => openBooking()} className="h-10"><Plus /> Novo agendamento</Button></div>
          <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-3 mb-5">{[
            { label: "Total de consultas", value: active.length, icon: CalendarDays, color: "text-primary", bg: "bg-info-soft", detail: `${day.filter(a => a.status === "concluído").length} concluídas` },
            { label: "Novos pacientes", value: day.filter(a => a.kind === "consulta" && a.status !== "cancelado").length, icon: UserRound, color: "text-primary", bg: "bg-info-soft", detail: "no dia selecionado" },
            { label: "Retornos", value: day.filter(a => a.kind === "retorno" && a.status !== "cancelado").length, icon: RotateCcw, color: "text-success", bg: "bg-success-soft", detail: "no dia selecionado" },
            { label: "Cancelados", value: day.filter(a => a.status === "cancelado").length, icon: X, color: "text-destructive", bg: "bg-danger-soft", detail: "no dia selecionado" },
            { label: "Próxima consulta", value: next ? timeLabel(next.time) : "—", icon: Clock3, color: "text-primary", bg: "bg-info-soft", detail: next ? shortDate(next.date) : "Nenhuma prevista" },
            { label: "Taxa de ocupação", value: `${isClosed ? 0 : Math.round(active.length / dailySlots.length * 100)}%`, icon: Activity, color: "text-primary", bg: "bg-info-soft", detail: `${active.length}/${isClosed ? 0 : dailySlots.length} horários` },
          ].map(card => <div key={card.label} className="panel p-3.5 min-h-[118px] flex flex-col justify-between"><div className="flex items-start justify-between gap-1"><div className={`size-8 rounded-md ${card.bg} ${card.color} grid place-items-center`}><card.icon className="size-4" /></div><span className="text-[11px] text-muted-foreground text-right leading-tight max-w-24">{card.label}</span></div><div><strong className="text-[22px] leading-none">{card.value}</strong><p className="text-[10px] text-muted-foreground mt-1">{card.detail}</p></div></div>)}</div>
          <div className="grid xl:grid-cols-[minmax(0,1fr)_290px] gap-5 items-start"><section className="panel overflow-hidden"><div className="p-4 border-b flex flex-wrap gap-3 items-center justify-between"><h2 className="font-bold flex items-center gap-2 text-sm"><CalendarDays className="size-4 text-primary" /> Agenda de Consultas</h2><div className="flex items-center gap-2"><Button variant="outline" size="icon" className="size-8" onClick={() => moveDate(-1)} aria-label="Dia anterior"><ChevronLeft /></Button><input type="date" aria-label="Selecionar data" className="field text-xs w-[145px] py-1.5" value={date} onChange={e => setDate(e.target.value)} /><Button variant="outline" size="icon" className="size-8" onClick={() => moveDate(1)} aria-label="Próximo dia"><ChevronRight /></Button><Button variant="ghost" size="sm" onClick={() => setDate(today())}>Hoje</Button></div></div><div className="px-4 py-2.5 bg-muted/50 text-xs text-muted-foreground capitalize flex justify-between"><span>{prettyDate(date)}</span><span>{isClosed ? "Consultório fechado" : `${dailySlots.length} horários`}</span></div>
            {isClosed ? <div className="py-20 text-center text-muted-foreground text-sm">Sem atendimento neste dia. Escolha um dia de funcionamento.</div> : <div className="max-h-[680px] overflow-auto px-3 py-2">{dailySlots.map(time => { const a = active.find(item => timeLabel(item.time) === time); const p = a && patientOf(a.patient_id); return <div key={time} className={`min-h-[49px] border-b last:border-0 flex items-center gap-2 sm:gap-4 px-2 border-l-[3px] ${a ? a.status === "concluído" ? "border-l-success" : a.status === "em atendimento" ? "border-l-primary" : "border-l-warning" : "border-l-border"}`}><strong className="text-xs w-11 shrink-0">{time}</strong><div className="hidden sm:block w-[105px] shrink-0"><Badge status={a?.status ?? "disponível"} /></div><div className="min-w-0 flex-1">{p ? <><p className="text-xs font-semibold truncate">{p.full_name}</p><p className="text-[10px] text-muted-foreground capitalize">{a?.kind}</p></> : <span className="text-xs text-muted-foreground sm:hidden">Disponível</span>}</div>{p && <span className="hidden md:block text-[11px] text-muted-foreground">{p.phone}</span>}<Button variant="outline" size="sm" className="h-7 px-2.5 text-[11px]" onClick={() => a ? (setSelectedAppointment(a), openPatient(p as Patient)) : openBooking(date, time)}>{a ? "Ver detalhes" : <><Plus className="size-3" /> Agendar</>}</Button></div>; })}</div>}</section>
            <aside className="space-y-4"><section className="panel p-4"><h2 className="font-bold text-sm flex items-center gap-2"><Search className="size-4 text-primary" /> Buscar paciente</h2><input className="field mt-3 text-xs" value={search} onChange={e => setSearch(e.target.value)} placeholder="Nome, telefone ou convênio..." />{search && <div className="mt-2 max-h-44 overflow-auto">{filteredPatients.slice(0, 5).map(p => <Button key={p.id} variant="ghost" className="w-full justify-start text-xs" onClick={() => openPatient(p)}>{p.full_name}</Button>)}</div>}</section><section className="panel p-4"><div className="flex justify-between items-center"><h2 className="font-bold text-sm">Pacientes do dia</h2><Button variant="link" size="sm" className="text-xs px-0" onClick={() => setView("pacientes")}>Ver todos</Button></div><div className="mt-2 max-h-[410px] overflow-auto">{active.length ? active.sort((a,b) => a.time.localeCompare(b.time)).map(a => { const p = patientOf(a.patient_id); return <Button variant="ghost" key={a.id} className="w-full h-auto py-2 px-0 rounded-none border-b last:border-0 justify-start text-left gap-2.5" onClick={() => { setSelectedAppointment(a); if (p) openPatient(p); }}><span className="size-8 rounded-full bg-success-soft text-success grid place-items-center text-xs font-bold shrink-0">{p?.full_name.slice(0,1)}</span><span className="flex-1 min-w-0"><span className="block text-xs font-semibold truncate">{p?.full_name}</span><span className="block text-[10px] text-muted-foreground capitalize">{a.kind}</span></span><span className="text-right"><Badge status={a.status} /><span className="block text-[10px] text-muted-foreground mt-1">{timeLabel(a.time)}</span></span></Button>; }) : <p className="text-xs text-muted-foreground py-5">Nenhuma consulta nesta data.</p>}</div></section><Button onClick={() => openBooking()} className="w-full h-12 justify-start"><span className="size-7 rounded-full bg-primary-foreground/20 grid place-items-center"><Plus /></span> Novo agendamento <ChevronRight className="ml-auto" /></Button></aside></div>
        </>}
        {view === "pacientes" && <><div className="flex flex-wrap justify-between items-start gap-3 mb-6"><div><h1 className="text-2xl font-extrabold">Pacientes</h1><p className="text-sm text-muted-foreground mt-1">{patients.length} pacientes cadastrados</p></div><div className="flex flex-wrap gap-2"><Button onClick={() => { setFichaId(""); setFicha(emptyFicha); setError(""); setModal("ficha"); }}><ClipboardList /> Ficha do paciente</Button><Button onClick={() => { setSelectedPatient(null); setForm(emptyForm); setModal("patient"); }}><Plus /> Novo paciente</Button></div></div><div className="panel overflow-hidden"><div className="p-4 border-b"><div className="relative max-w-md"><Search className="absolute left-3 top-3 size-4 text-muted-foreground" /><input className="field pl-9" placeholder="Buscar por nome, telefone ou convênio..." value={search} onChange={e => setSearch(e.target.value)} /></div></div>{filteredPatients.length ? filteredPatients.map(p => <div key={p.id} className="flex items-center gap-3 p-4 border-b last:border-0"><span className="size-10 rounded-full bg-info-soft text-primary grid place-items-center font-bold">{p.full_name.slice(0,1).toUpperCase()}</span><div className="min-w-0 flex-1"><p className="font-semibold text-sm truncate">{p.full_name}</p><p className="text-xs text-muted-foreground">{p.phone} · Convênio {p.convenio || "—"}</p></div><span className="text-xs text-muted-foreground hidden md:block">{appointments.filter(a => a.patient_id === p.id && a.status === "concluído").length} consultas realizadas</span><Button variant="outline" size="sm" onClick={() => openPatient(p)}>Ver detalhes</Button></div>) : <p className="text-muted-foreground text-sm p-8 text-center">Nenhum paciente encontrado.</p>}</div></>}
        {view === "relatorios" && <><h1 className="text-2xl font-extrabold mb-1">Relatórios</h1><p className="text-sm text-muted-foreground mb-6">Visão geral do seu consultório</p><div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-4">{[{ label: "Pacientes cadastrados", value: patients.length, icon: Users }, { label: "Consultas realizadas", value: appointments.filter(a => a.status === "concluído").length, icon: Check }, { label: "Retornos", value: appointments.filter(a => a.kind === "retorno" && a.status !== "cancelado").length, icon: RotateCcw }, { label: "Cancelamentos", value: cancelled.length, icon: CalendarX2 }].map(item => <div className="panel p-5" key={item.label}><item.icon className="size-6 text-primary mb-5" /><strong className="block text-3xl">{item.value}</strong><p className="text-muted-foreground text-sm mt-2">{item.label}</p></div>)}</div><section className="mt-6 panel p-5"><h2 className="font-bold mb-4">Consultas recentes</h2>{appointments.slice(0, 10).map(a => <div key={a.id} className="flex items-center justify-between gap-3 border-b last:border-0 py-3 text-sm"><span className="truncate">{patientOf(a.patient_id)?.full_name}</span><span className="text-muted-foreground shrink-0">{shortDate(a.date)}</span><Badge status={a.status} /></div>)}{!appointments.length && <p className="text-muted-foreground text-sm">Ainda não há consultas.</p>}</section></>}
        {view === "configuracoes" && <><h1 className="text-2xl font-extrabold mb-1">Configurações</h1><p className="text-sm text-muted-foreground mb-6">Personalize os horários do consultório</p><form onSubmit={saveSchedule} className="panel p-5 md:p-7 max-w-xl"><h2 className="font-bold flex items-center gap-2 mb-1"><Clock3 className="size-5 text-primary" /> Horários de funcionamento</h2><p className="text-sm text-muted-foreground mb-6">Atendimento de segunda a sexta-feira.</p><div className="grid sm:grid-cols-2 gap-4"><label className="text-sm font-semibold">Início<input className="field mt-2" type="time" required value={timeLabel(schedule.start_time)} onChange={e => setGlobalTime("start_time", e.target.value)} /></label><label className="text-sm font-semibold">Fim<input className="field mt-2" type="time" required value={timeLabel(schedule.end_time)} onChange={e => setGlobalTime("end_time", e.target.value)} /></label></div><label className="block text-sm font-semibold mt-5">Intervalo entre consultas<select className="field mt-2" value={schedule.interval_minutes} onChange={e => setSchedule({ ...schedule, interval_minutes: Number(e.target.value) })}><option value={15}>15 minutos</option><option value={30}>30 minutos</option><option value={60}>60 minutos</option></select></label><label className="block text-sm font-semibold mt-5">Dias da semana<select className="field mt-2" value={dayKey} onChange={e => setDayKey(e.target.value as DayKey)}>{DAYS.map(([k, label]) => <option key={k} value={k}>{label}</option>)}</select></label>{(() => { const d = weekDays(schedule)[dayKey]; const label = DAYS.find(([k]) => k === dayKey)?.[1] ?? ""; return <><label className="text-sm font-semibold flex items-center gap-2 mt-4"><input type="checkbox" className="size-4 accent-primary" checked={d.open} onChange={e => setDay(dayKey, { open: e.target.checked })} />{d.open ? "Aberto" : "Fechado"}</label><div className="grid sm:grid-cols-2 gap-4 mt-4"><label className="text-sm font-semibold">Início ({label})<input className="field mt-2 disabled:opacity-50" type="time" required={d.open} disabled={!d.open} value={d.start} onChange={e => setDay(dayKey, { start: e.target.value })} /></label><label className="text-sm font-semibold">Fim ({label})<input className="field mt-2 disabled:opacity-50" type="time" required={d.open} disabled={!d.open} value={d.end} onChange={e => setDay(dayKey, { end: e.target.value })} /></label></div></>; })()}<p className="text-xs text-muted-foreground mt-4">A alteração não modifica consultas já agendadas.</p><Button className="mt-6" disabled={saving}>Salvar horários</Button></form></>}
        </>}
      </main>
    </div>
    <Dialog open={modal === "booking"} onOpenChange={open => !open && close()}><DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Novo agendamento</DialogTitle><DialogDescription>Escolha um paciente, uma data e um horário disponível.</DialogDescription></DialogHeader><form onSubmit={book} className="space-y-4"><div><label className="text-sm font-semibold">Paciente</label>{bookingPatient && !newPatient ? <div className="field mt-2 flex items-center justify-between"><span>{patientOf(bookingPatient)?.full_name}</span><Button type="button" variant="ghost" size="icon" onClick={() => { setBookingPatient(""); setBookingSearch(""); }} aria-label="Trocar paciente"><X /></Button></div> : <><input className="field mt-2" placeholder="Buscar nome, telefone ou convênio" value={bookingSearch} onChange={e => setBookingSearch(e.target.value)} />{bookingSearch && <div className="border rounded-md mt-1 max-h-40 overflow-auto">{patients.filter(p => `${p.full_name} ${p.phone} ${p.convenio ?? ""}`.toLowerCase().includes(bookingSearch.toLowerCase())).slice(0, 8).map(p => <Button type="button" variant="ghost" className="w-full justify-start" key={p.id} onClick={() => { setBookingPatient(p.id); setBookingSearch(p.full_name); }}>{p.full_name}</Button>)}</div>}<Button type="button" variant="link" className="px-0 mt-1" onClick={() => { setSelectedPatient(null); setForm(emptyForm); setNewPatient(true); setModal("patient"); }}><Plus /> Cadastrar novo paciente</Button></>}</div><div className="grid grid-cols-2 gap-3"><label className="text-sm font-semibold">Data<input className="field mt-2" type="date" required value={bookingDate} onChange={e => { setBookingDate(e.target.value); setBookingTime(""); }} /></label><label className="text-sm font-semibold">Horário<select className="field mt-2" required value={bookingTime} onChange={e => setBookingTime(e.target.value)} disabled={bookingClosed}><option value="">Selecione</option>{bookingSlots.filter(t => !appointments.some(a => a.date === bookingDate && timeLabel(a.time) === t && a.status !== "cancelado")).map(t => <option key={t} value={t}>{t}</option>)}</select></label></div>{bookingClosed && <p className="text-xs text-destructive">O consultório não atende neste dia.</p>}{bookingPatient && (() => { const info = lastVisitInfo(appointments, bookingPatient, bookingDate); return <div className="rounded-md border p-3 space-y-2"><div className="flex items-center justify-between text-sm"><span className="text-muted-foreground">Convênio</span><ConvenioTag name={patientOf(bookingPatient)?.convenio ?? null} /></div><div className="flex items-center justify-between text-sm"><span className="font-semibold">Tipo de consulta</span><span className={`px-3 py-1 rounded-md text-xs font-extrabold tracking-wide ${info.isReturn ? "bg-warning-soft text-warning-foreground" : "bg-success-soft text-success"}`}>{info.isReturn ? "RETORNO" : "CONSULTA NORMAL"}</span></div><p className="text-xs text-muted-foreground">{info.last ? `Última consulta há ${info.days} dia${info.days === 1 ? "" : "s"} (${shortDate(info.last.date)}). Este atendimento será registrado como ${info.isReturn ? "retorno" : "consulta normal"}.` : "Nenhuma consulta realizada anteriormente. Este atendimento será registrado como consulta normal."}</p></div>; })()}{error && <p role="alert" className="text-sm text-destructive">{error}</p>}<Button className="w-full" disabled={saving || bookingClosed}>{saving ? "Salvando..." : "Confirmar agendamento"}</Button></form></DialogContent></Dialog>
    <Dialog open={modal === "patient"} onOpenChange={open => !open && close()}><DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>{selectedPatient ? "Editar paciente" : "Cadastrar paciente"}</DialogTitle><DialogDescription>Dados do paciente para consultas e histórico.</DialogDescription></DialogHeader><form onSubmit={newPatient ? createPatient : async e => { const p = await savePatient(e); if (p) close(); }} className="space-y-3"><label className="block text-sm font-semibold">Nome completo *<input className="field mt-1" required maxLength={120} value={form.full_name} onChange={e => setForm({ ...form, full_name: e.target.value })} /></label><div className="grid grid-cols-2 gap-3"><label className="text-sm font-semibold">Telefone *<input className="field mt-1" required maxLength={30} value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} /></label><div className="col-span-2 text-sm font-semibold" role="radiogroup" aria-label="Convênio">Convênio *<div className="grid grid-cols-3 gap-2 mt-1">{CONVENIOS.map(c => <button type="button" role="radio" aria-checked={form.convenio === c.name} key={c.name} onClick={() => setForm({ ...form, convenio: c.name })} className={`rounded-md border p-2 flex flex-col items-center gap-1.5 text-xs transition ${form.convenio === c.name ? "border-primary ring-2 ring-primary/30 bg-info-soft" : "border-border hover:bg-muted"}`}><img src={c.logo} alt={`Logo ${c.name}`} className="h-9 w-full object-contain" />{c.name}</button>)}</div></div></div><div className="grid grid-cols-2 gap-3"><label className="text-sm font-semibold">Nascimento<input className="field mt-1" type="date" value={form.birth_date} onChange={e => setForm({ ...form, birth_date: e.target.value })} /></label><label className="text-sm font-semibold">E-mail<input className="field mt-1" type="email" maxLength={255} value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></label></div><label className="block text-sm font-semibold">Endereço<input className="field mt-1" maxLength={300} value={form.address} onChange={e => setForm({ ...form, address: e.target.value })} placeholder="Rua, número, bairro, cidade" /></label><div className="grid grid-cols-2 gap-3"><label className="text-sm font-semibold">Naturalidade<input className="field mt-1" maxLength={120} value={form.birthplace} onChange={e => setForm({ ...form, birthplace: e.target.value })} placeholder="Cidade / UF" /></label><label className="text-sm font-semibold">Estado civil<select className="field mt-1" value={form.marital_status} onChange={e => setForm({ ...form, marital_status: e.target.value })}><option value="">Selecione</option>{MARITAL.map(m => <option key={m} value={m}>{m}</option>)}{form.marital_status && !MARITAL.includes(form.marital_status as (typeof MARITAL)[number]) && <option value={form.marital_status}>{form.marital_status}</option>}</select></label></div><label className="block text-sm font-semibold">Observações<textarea className="field mt-1 min-h-20" maxLength={2000} value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} /></label>{error && <p role="alert" className="text-destructive text-sm">{error}</p>}<Button disabled={saving} className="w-full">{saving ? "Salvando..." : selectedPatient ? "Salvar alterações" : "Salvar paciente"}</Button></form></DialogContent></Dialog>
    <Dialog open={modal === "detail"} onOpenChange={open => !open && close()}><DialogContent className="max-w-xl max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>{selectedPatient?.full_name}</DialogTitle><DialogDescription>Dados cadastrais e histórico de consultas.</DialogDescription></DialogHeader>{selectedPatient && <><div className="grid grid-cols-2 gap-3 text-sm bg-muted/50 rounded-md p-4"><div><span className="text-muted-foreground">Telefone</span><p className="font-semibold">{selectedPatient.phone}</p></div><div><span className="text-muted-foreground">Convênio</span><p><ConvenioTag name={selectedPatient.convenio} /></p></div>{(() => { const info = lastVisitInfo(appointments, selectedPatient.id, format(new Date(), "yyyy-MM-dd")); return <div className="col-span-2 border-t pt-3 grid grid-cols-2 gap-3"><div><span className="text-muted-foreground">Última consulta</span><p className="font-semibold">{info.last ? shortDate(info.last.date) : "Nenhuma consulta registrada"}</p>{info.days !== null && <p className="text-xs text-muted-foreground">{info.days === 0 ? "Hoje" : `Há ${info.days} dia${info.days === 1 ? "" : "s"}`}</p>}</div><div><span className="text-muted-foreground">Tipo do próximo atendimento</span><p><span className={`inline-block mt-0.5 px-2 py-0.5 rounded text-xs font-bold ${info.isReturn ? "bg-warning-soft text-warning-foreground" : "bg-success-soft text-success"}`}>{info.isReturn ? "Retorno" : "Consulta normal"}</span></p></div></div>; })()}<div><span className="text-muted-foreground">Nascimento</span><p>{selectedPatient.birth_date ? shortDate(selectedPatient.birth_date) : "—"}</p></div><div><span className="text-muted-foreground">E-mail</span><p className="break-all">{selectedPatient.email || "—"}</p></div><div className="col-span-2"><span className="text-muted-foreground">Endereço</span><p>{selectedPatient.address || "—"}</p></div><div><span className="text-muted-foreground">Naturalidade</span><p>{selectedPatient.birthplace || "—"}</p></div><div><span className="text-muted-foreground">Estado civil</span><p>{selectedPatient.marital_status || "—"}</p></div>{selectedPatient.notes && <div className="col-span-2"><span className="text-muted-foreground">Observações</span><p>{selectedPatient.notes}</p></div>}</div><div className="grid grid-cols-3 gap-2 text-center text-xs"><div className="bg-info-soft p-2 rounded-md"><strong className="block text-lg">{patientHistory.filter(a => a.status === "concluído").length}</strong>Realizadas</div><div className="bg-danger-soft p-2 rounded-md"><strong className="block text-lg">{patientHistory.filter(a => a.status === "cancelado").length}</strong>Canceladas</div><div className="bg-success-soft p-2 rounded-md"><strong className="block text-lg">{patientHistory.filter(a => a.status !== "cancelado" && a.date >= today()).length}</strong>Próximas</div></div><div className="flex gap-2"><Button variant="outline" size="sm" onClick={() => openPatient(selectedPatient, true)}><Pencil /> Editar</Button><Button size="sm" onClick={() => openBooking(date, "", selectedPatient.id)}><Plus /> Agendar</Button></div><div><h3 className="font-bold text-sm mb-2">Histórico de consultas</h3><div className="max-h-64 overflow-auto">{patientHistory.length ? patientHistory.map(a => <div key={a.id} className="py-3 border-b last:border-0 flex items-center gap-2"><div className="flex-1 min-w-0"><p className="text-xs font-semibold capitalize">{shortDate(a.date)} · {timeLabel(a.time)} — {a.kind === "retorno" ? "Retorno" : "Consulta normal"}{a.id === lastVisitInfo(appointments, a.patient_id, "9999-12-31").last?.id && <span className="ml-2 normal-case px-1.5 py-0.5 rounded bg-info-soft text-primary text-[10px]">Última consulta</span>}</p>{a.cancellation_reason && <p className="text-xs text-muted-foreground">Motivo: {a.cancellation_reason}</p>}</div><Badge status={a.status} />{a.status !== "cancelado" && a.status !== "concluído" && <Button variant="ghost" size="icon" title="Gerenciar consulta" aria-label="Gerenciar consulta" onClick={() => setSelectedAppointment(a)}><MoreVertical /></Button>}{a.status === "cancelado" && <Button variant="ghost" size="icon" title="Remarcar" aria-label="Remarcar" onClick={() => openBooking(date, "", a.patient_id)}><RotateCcw /></Button>}</div>) : <p className="text-xs text-muted-foreground">Nenhuma consulta registrada.</p>}</div></div>{selectedAppointment && selectedAppointment.patient_id === selectedPatient.id && selectedAppointment.status !== "concluído" && selectedAppointment.status !== "cancelado" && <div className="border-t pt-4"><p className="text-xs font-semibold mb-2">Consulta de {shortDate(selectedAppointment.date)} às {timeLabel(selectedAppointment.time)}</p><div className="flex flex-wrap gap-2">{selectedAppointment.status === "agendado" && <Button size="sm" variant="outline" onClick={() => updateStatus(selectedAppointment, "em atendimento")} disabled={saving}>Iniciar atendimento</Button>}{selectedAppointment.status === "em atendimento" && <Button size="sm" onClick={() => updateStatus(selectedAppointment, "concluído")} disabled={saving}>Concluir consulta</Button>}<Button size="sm" variant="destructive" onClick={() => { setReason(""); setModal("cancel"); }}>Cancelar consulta</Button></div></div>}</>}</DialogContent></Dialog>
    <Dialog open={modal === "ficha"} onOpenChange={open => !open && close()}><DialogContent className="max-w-4xl max-h-[92vh] overflow-y-auto"><DialogHeader className="print:hidden"><DialogTitle>Ficha do paciente</DialogTitle><DialogDescription>Escolha um paciente ou comece em branco. Preencha ou corrija os dados direto na ficha e depois imprima.</DialogDescription></DialogHeader><div className="flex flex-wrap gap-2 items-end print:hidden"><label className="text-sm font-semibold flex-1 min-w-[220px]">Paciente<select className="field mt-1" value={fichaId} onChange={e => pickFicha(e.target.value)}><option value="">Ficha em branco (novo paciente)</option>{patients.map(p => <option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label><Button variant="outline" onClick={() => void saveFicha()} disabled={saving}><Check /> {saving ? "Salvando..." : fichaId ? "Salvar no cadastro" : "Cadastrar paciente"}</Button><Button onClick={() => window.print()}><Printer /> Imprimir</Button></div>{error && <p role="alert" className="text-sm text-destructive print:hidden">{error}</p>}<FichaPaciente value={ficha} onChange={patch => setFicha(f => ({ ...f, ...patch }))} />{createPortal(<div className="print-only"><FichaPaciente staticMode value={ficha} onChange={() => {}} /></div>, document.body)}<p className="text-xs text-muted-foreground print:hidden">Você pode imprimir sem salvar. Para guardar os dados no cadastro, clique em "{fichaId ? "Salvar no cadastro" : "Cadastrar paciente"}".</p></DialogContent></Dialog>
    <Dialog open={modal === "cancel"} onOpenChange={open => !open && close()}><DialogContent className="max-w-sm"><DialogHeader><DialogTitle>Cancelar consulta?</DialogTitle><DialogDescription>O cancelamento ficará no histórico e o horário será liberado para outro paciente.</DialogDescription></DialogHeader><label className="text-sm font-semibold">Motivo (opcional)<textarea className="field mt-2" maxLength={500} value={reason} onChange={e => setReason(e.target.value)} placeholder="Informe o motivo..." /></label>{error && <p className="text-destructive text-sm">{error}</p>}<div className="flex justify-end gap-2"><Button variant="outline" onClick={() => setModal("detail")}>Voltar</Button><Button variant="destructive" disabled={saving} onClick={() => selectedAppointment && updateStatus(selectedAppointment, "cancelado", reason.trim() || null)}>Confirmar cancelamento</Button></div></DialogContent></Dialog>
  </div>;
}